From: Apoorv Dixit <apoorv.dixit@juspay.in>
Date: Thu, 12 Feb 2026 15:45:34 +0530
Subject: [PATCH 1/3] fix(authorization): add backward compatibility for
 incremental authorization queries

---
 .../diesel_models/src/query/authorization.rs  | 58 ++++++++++++
 crates/router/src/db/authorization.rs         | 90 +++++++++++++++----
 2 files changed, 133 insertions(+), 15 deletions(-)

diff --git a/crates/diesel_models/src/query/authorization.rs b/crates/diesel_models/src/query/authorization.rs
index 8423ed0f13c..86e2b10d375 100644
--- a/crates/diesel_models/src/query/authorization.rs
+++ b/crates/diesel_models/src/query/authorization.rs
@@ -56,6 +56,46 @@ impl Authorization {
         }
     }

+    // Fallback function for stagger release - updates by merchant_id when processor_merchant_id is NULL
+    pub async fn update_by_merchant_id_authorization_id(
+        conn: &PgPooledConn,
+        merchant_id: common_utils::id_type::MerchantId,
+        authorization_id: String,
+        authorization_update: AuthorizationUpdate,
+    ) -> StorageResult<Self> {
+        match generics::generic_update_with_unique_predicate_get_result::<
+            <Self as HasTable>::Table,
+            _,
+            _,
+            _,
+        >(
+            conn,
+            dsl::merchant_id
+                .eq(merchant_id.to_owned())
+                .and(dsl::authorization_id.eq(authorization_id.to_owned())),
+            AuthorizationUpdateInternal::from(authorization_update),
+        )
+        .await
+        {
+            Err(error) => match error.current_context() {
+                errors::DatabaseError::NotFound => Err(error.attach_printable(
+                    "Authorization with the given Authorization ID does not exist",
+                )),
+                errors::DatabaseError::NoFieldsToUpdate => {
+                    generics::generic_find_one::<<Self as HasTable>::Table, _, _>(
+                        conn,
+                        dsl::merchant_id
+                            .eq(merchant_id.to_owned())
+                            .and(dsl::authorization_id.eq(authorization_id.to_owned())),
+                    )
+                    .await
+                }
+                _ => Err(error),
+            },
+            result => result,
+        }
